package main

import (
	"math"
	"math/bits"
)

// op is an operator held on the evaluator's operator stack.
type op byte

const (
	opNeg op = iota
	opAdd
	opSub
	opMul
	opDiv
	opMod
	opLParen
)

func (o op) precedence() int {
	switch o {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opMod:
		return 2
	case opNeg:
		return 3
	default: // opLParen
		return 0
	}
}

func binaryOp(c byte) (op, bool) {
	switch c {
	case '+':
		return opAdd, true
	case '-':
		return opSub, true
	case '*':
		return opMul, true
	case '/':
		return opDiv, true
	case '%':
		return opMod, true
	}
	return 0, false
}

func negate(a int64) (int64, bool) {
	if a == math.MinInt64 {
		return 0, false
	}
	return -a, true
}

func mulChecked(a, b int64) (int64, bool) {
	neg := (a < 0) != (b < 0)
	hi, lo := bits.Mul64(absU64(a), absU64(b))
	if hi != 0 {
		return 0, false
	}
	if neg {
		if lo > 1<<63 {
			return 0, false
		}
		return int64(-lo), true
	}
	if lo > math.MaxInt64 {
		return 0, false
	}
	return int64(lo), true
}

func absU64(a int64) uint64 {
	if a < 0 {
		return -uint64(a)
	}
	return uint64(a)
}

// apply evaluates a binary operator, reporting false on overflow or division by zero.
func apply(o op, a, b int64) (int64, bool) {
	switch o {
	case opAdd:
		r := a + b
		if (a >= 0) == (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, false
		}
		return r, true
	case opSub:
		r := a - b
		if (a >= 0) != (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, false
		}
		return r, true
	case opMul:
		return mulChecked(a, b)
	case opDiv:
		if b == 0 || (a == math.MinInt64 && b == -1) {
			return 0, false
		}
		return a / b, true
	case opMod:
		if b == 0 {
			return 0, false
		}
		return a % b, true // Go defines MinInt64 % -1 == 0.
	}
	return 0, false
}

// evaluator is an iterative operator-precedence parser, so arbitrarily deep
// nesting cannot overflow the call stack. Its stacks are reused across lines.
type evaluator struct {
	values []int64
	ops    []op
}

// evaluate returns the value of line, or false on any syntax or arithmetic error.
func (e *evaluator) evaluate(line []byte) (int64, bool) {
	e.values = e.values[:0]
	e.ops = e.ops[:0]

	expectOperand := true
	n := len(line)
	for i := 0; ; {
		for i < n && isBlank(line[i]) {
			i++
		}
		if i == n {
			break
		}
		c := line[i]

		if expectOperand {
			switch {
			case c == '-':
				e.ops = append(e.ops, opNeg)
				i++
			case c == '(':
				e.ops = append(e.ops, opLParen)
				i++
			case isDigit(c):
				v, next, ok := parseNumber(line, i)
				if !ok {
					return 0, false
				}
				e.values = append(e.values, v)
				i = next
				expectOperand = false
			default:
				return 0, false
			}
			continue
		}

		if c == ')' {
			if !e.reduceUntilParen() || len(e.ops) == 0 {
				return 0, false // arithmetic error or unmatched ')'
			}
			e.ops = e.ops[:len(e.ops)-1]
			i++
			continue
		}
		o, ok := binaryOp(c)
		if !ok {
			return 0, false
		}
		p := o.precedence()
		for len(e.ops) > 0 && e.ops[len(e.ops)-1].precedence() >= p {
			if !e.reduceOnce() {
				return 0, false
			}
		}
		e.ops = append(e.ops, o)
		expectOperand = true
		i++
	}

	if expectOperand || !e.reduceUntilParen() {
		return 0, false
	}
	if len(e.ops) != 0 || len(e.values) != 1 {
		return 0, false // unmatched '('
	}
	return e.values[0], true
}

// parseNumber parses the digits starting at line[i], returning the value and
// the index just past them; it reports false if the literal exceeds MaxInt64.
func parseNumber(line []byte, i int) (int64, int, bool) {
	var v int64
	overflow := false
	for ; i < len(line) && isDigit(line[i]); i++ {
		d := int64(line[i] - '0')
		if v > (math.MaxInt64-d)/10 {
			overflow = true
		} else if !overflow {
			v = v*10 + d
		}
	}
	return v, i, !overflow
}

// reduceUntilParen applies operators until the stack is empty or its top is '('.
func (e *evaluator) reduceUntilParen() bool {
	for len(e.ops) > 0 && e.ops[len(e.ops)-1] != opLParen {
		if !e.reduceOnce() {
			return false
		}
	}
	return true
}

// reduceOnce pops the top operator and applies it to the value stack.
func (e *evaluator) reduceOnce() bool {
	o := e.ops[len(e.ops)-1]
	e.ops = e.ops[:len(e.ops)-1]

	var (
		r  int64
		ok bool
	)
	top := len(e.values) - 1
	if o == opNeg {
		r, ok = negate(e.values[top])
		e.values = e.values[:top]
	} else {
		a, b := e.values[top-1], e.values[top]
		r, ok = apply(o, a, b)
		e.values = e.values[:top-1]
	}
	if !ok {
		return false
	}
	e.values = append(e.values, r)
	return true
}

package main

import (
	"strconv"
	"strings"
	"testing"
)

func TestEvaluate(t *testing.T) {
	tests := []struct {
		in   string
		want string
	}{
		{"1 + 2 * 3", "7"},
		{"-7 / 2", "-3"},
		{"-7 % 3", "-1"},
		{"7 % -3", "1"},
		{"10 - 4 - 3", "3"},
		{"--5", "5"},
		{"-(2 + 3)", "-5"},
		{"(1 + 2", "error"},
		{"1 2", "error"},
		{"+1", "error"},
		{"()", "error"},
		{"1)", "error"},
		{"1 / 0", "error"},
		{"5 % 0", "error"},
		{"9223372036854775807", "9223372036854775807"},
		{"9223372036854775808", "error"},
		{"9223372036854775807 + 1", "error"},
		{"-9223372036854775807 - 1", "-9223372036854775808"},
		{"-9223372036854775807 - 2", "error"},
		{"(-9223372036854775807 - 1) % -1", "0"},
		{"(-9223372036854775807 - 1) / -1", "error"},
		{"-(-9223372036854775807 - 1)", "error"},
		{"3037000500 * 3037000500", "error"},
		{"-4294967296 * 2147483648", "-9223372036854775808"},
		{"4294967296 * 2147483648", "error"},
	}
	var ev evaluator
	for _, tt := range tests {
		got := "error"
		if v, ok := ev.evaluate([]byte(tt.in)); ok {
			got = strconv.FormatInt(v, 10)
		}
		if got != tt.want {
			t.Errorf("evaluate(%q) = %s, want %s", tt.in, got, tt.want)
		}
	}
}

func TestRunSkipsBlankLines(t *testing.T) {
	var out strings.Builder
	if err := run(strings.NewReader("\n  42  \n\t\n1+1"), &out); err != nil {
		t.Fatal(err)
	}
	if got, want := out.String(), "42\n2\n"; got != want {
		t.Errorf("run output = %q, want %q", got, want)
	}
}

func TestDeepNesting(t *testing.T) {
	const depth = 1_000_000
	line := strings.Repeat("(", depth) + "1" + strings.Repeat(")", depth)
	var ev evaluator
	if v, ok := ev.evaluate([]byte(line)); !ok || v != 1 {
		t.Errorf("deep nesting = %d, %v; want 1, true", v, ok)
	}
}

// Command calc is a 64-bit signed integer expression evaluator (see SPEC.md).
//
// Each line of standard input is one expression; for each non-blank line the
// program prints its value or "error".
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "calc:", err)
	}
}

// run evaluates every line of r and writes the results to w.
func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}

	out := bufio.NewWriterSize(w, 64*1024)
	var ev evaluator
	var buf []byte

	for len(input) > 0 {
		line := input
		if i := bytes.IndexByte(input, '\n'); i >= 0 {
			line, input = input[:i], input[i+1:]
		} else {
			input = nil
		}
		if isBlankLine(line) {
			continue
		}
		buf = buf[:0]
		if v, ok := ev.evaluate(line); ok {
			buf = strconv.AppendInt(buf, v, 10)
		} else {
			buf = append(buf, "error"...)
		}
		buf = append(buf, '\n')
		if _, err := out.Write(buf); err != nil {
			return err
		}
	}
	return out.Flush()
}

func isBlank(c byte) bool { return c == ' ' || c == '\t' }

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isBlankLine(line []byte) bool {
	for _, c := range line {
		if !isBlank(c) {
			return false
		}
	}
	return true
}
